import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { formatOrganizationDate, formatOrganizationMoney } from "@/lib/organizationFormat";
import { Progress } from "@/components/ui/progress";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { format, formatDistanceToNowStrict, isPast } from "date-fns";
import { Activity, ArrowDownToLine, ArrowUpRight, BarChart3, Bell, BriefcaseBusiness, CalendarClock, Check, CheckCircle2, CheckSquare, ChevronLeft, ChevronRight, CircleAlert, Clock3, Download, FileArchive, FilePlus2, FileText, Filter, FolderKanban, ListFilter, Loader2, MoreHorizontal, Pencil, Plus, Search, ShieldCheck, Sparkles, Trash2, UploadCloud, UsersRound, X } from "lucide-react";
import { useMemo, useState } from "react";
import { Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { toast } from "sonner";
import { useLocation } from "wouter";

const statusStyles: Record<string, string> = {
  active: "bg-[#DCFCE7] text-[#197A46]", planning: "bg-[#EEF2FF] text-[#4F46E5]", on_hold: "bg-[#FFF4D6] text-[#A75D00]", complete: "bg-[#E7F7F0] text-[#157A57]", archived: "bg-[#F1F3F7] text-[#64748B]",
  open: "bg-[#EAF1FF] text-[#195FE6]", investigating: "bg-[#F3E8FF] text-[#7E22CE]", pending: "bg-[#FFF4D6] text-[#A75D00]", resolved: "bg-[#E7F7F0] text-[#157A57]", closed: "bg-[#F1F3F7] text-[#64748B]",
  todo: "bg-[#EEF2FF] text-[#4F46E5]", in_progress: "bg-[#EAF1FF] text-[#195FE6]", blocked: "bg-[#FFF0F2] text-[#C63550]", lead: "bg-[#FFF4D6] text-[#A75D00]", inactive: "bg-[#F1F3F7] text-[#64748B]",
};
const priorityStyles: Record<string, string> = { urgent: "text-[#D12B48]", high: "text-[#DD7A00]", medium: "text-[#195FE6]", low: "text-[#64748B]", critical: "text-[#D12B48]" };
const pretty = (value?: string | null) => (value || "—").replace(/_/g, " ").replace(/\b\w/g, letter => letter.toUpperCase());
const stamp = (date?: string | Date | null) => date ? formatOrganizationDate(date) : "No date";
const compactMoney = (value?: number | null) => value ? formatOrganizationMoney(value, undefined, { notation: "compact", maximumFractionDigits: 1 }) : "—";

export function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="elegex-eyebrow">{eyebrow || "ELEGEX WORKSPACE"}</p><h1 className="elegex-page-title mt-2">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#667085]">{description}</p></div>{action}</div>;
}

function StatCard({ label, value, detail, icon: Icon, tone = "blue" }: { label: string; value: string | number; detail: string; icon: any; tone?: "blue" | "green" | "amber" | "rose" }) {
  const tones = { blue: "bg-[#EAF1FF] text-[#195FE6]", green: "bg-[#E8F8EF] text-[#198754]", amber: "bg-[#FFF4D6] text-[#B66700]", rose: "bg-[#FFF0F2] text-[#D12B48]" };
  return <div className="elegex-card p-5"><div className="flex items-start justify-between"><p className="elegex-eyebrow">{label}</p><span className={`grid h-9 w-9 place-items-center rounded-xl ${tones[tone]}`}><Icon className="h-[18px] w-[18px]" /></span></div><p className="mt-5 text-3xl font-semibold tracking-[-0.04em] text-[#14213D]">{value}</p><p className="mt-2 text-xs text-[#7A879E]">{detail}</p></div>;
}

export function DashboardHome() {
  const dashboard = trpc.elegex.dashboard.useQuery();
  const operational = trpc.elegex.workspace.operationalSettings.useQuery();
  const stamp = (date?: string | Date | null) => date ? formatOrganizationDate(date, operational.data?.settings) : "No date";
  const [range, setRange] = useState("This month");
  const [showSetup, setShowSetup] = useState(true);
  const [, setLocation] = useLocation();
  if (dashboard.isLoading) return <PageLoading />;
  const data = dashboard.data!;
  const projectRows = data.projectRows as any[];
  const taskRows = data.taskRows as any[];
  const totalProjects = projectRows.reduce((sum, item) => sum + Number(item.total), 0);
  const activeProjects = projectRows.find(item => item.status === "active")?.total || 0;
  const projectChart = projectRows.map(item => ({ name: pretty(item.status), value: Number(item.total), fill: item.status === "active" ? "#195FE6" : item.status === "complete" ? "#27A96B" : "#91A4C5" }));
  const taskChart = taskRows.map(item => ({ name: pretty(item.status), value: Number(item.total) }));
  return <><PageHeading eyebrow="OPERATIONS COMMAND CENTRE" title="Work that stays moving." description="A focused view of your active portfolio, delivery workload, and the signals that need attention." action={<select value={range} onChange={event => setRange(event.target.value)} className="h-10 rounded-xl border border-[#DFE7F3] bg-white px-3 text-sm font-medium text-[#4B5C7A] shadow-sm"><option>This month</option><option>This quarter</option><option>Year to date</option></select>} />{showSetup ? <section className="mb-5 rounded-2xl border border-[#CFE0FF] bg-[linear-gradient(105deg,#EAF2FF,#F8FBFF)] p-5"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center"><div className="flex gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#195FE6] text-white"><Sparkles className="h-5 w-5" /></span><div><p className="text-sm font-semibold text-[#14213D]">Your private Elegex workspace is ready.</p><p className="mt-1 text-sm leading-6 text-[#50617F]">The initial demonstration portfolio is live. Complete the quick setup to make the workspace yours.</p></div></div><div className="flex flex-wrap items-center gap-2"><Button variant="outline" onClick={() => setLocation("/settings")} className="rounded-xl bg-white">Name workspace</Button><Button variant="outline" onClick={() => setLocation("/admin")} className="rounded-xl bg-white">Review roles</Button><button onClick={() => setShowSetup(false)} className="p-2 text-[#7A879E] hover:text-[#195FE6]" aria-label="Dismiss setup guidance"><X className="h-4 w-4" /></button></div></div></section> : null}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Active projects" value={activeProjects} detail={`${totalProjects} programmes in the workspace`} icon={FolderKanban} /><StatCard label="Open cases" value={data.caseRows.filter((row: any) => !["resolved", "closed"].includes(row.status)).reduce((sum: number, row: any) => sum + Number(row.total), 0)} detail="Across active client programmes" icon={BriefcaseBusiness} tone="amber" /><StatCard label="Contacts" value={data.contacts} detail="Relationships currently in view" icon={UsersRound} tone="green" /><StatCard label="Unread signals" value={data.unread} detail="New activity and assignments" icon={Bell} tone="rose" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.3fr_0.9fr]"><section className="elegex-card p-6"><div className="flex items-start justify-between"><div><p className="elegex-eyebrow">PORTFOLIO STATUS</p><h2 className="mt-2 text-lg font-semibold tracking-[-0.02em] text-[#14213D]">Project momentum</h2></div><span className="rounded-full bg-[#F2F6FF] px-3 py-1 text-xs font-semibold text-[#195FE6]">{range}</span></div><div className="mt-7 h-[260px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={projectChart} margin={{ left: -22, right: 6, top: 8 }}><CartesianGrid vertical={false} stroke="#EDF1F7" /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: "#7A879E", fontSize: 11 }} /><YAxis allowDecimals={false} axisLine={false} tickLine={false} tick={{ fill: "#98A2B3", fontSize: 11 }} /><Tooltip cursor={{ fill: "#F7F9FD" }} contentStyle={{ borderRadius: 12, border: "1px solid #E7ECF5", fontSize: 12 }} /><Bar dataKey="value" radius={[8, 8, 3, 3]}>{projectChart.map((row, index) => <Cell key={index} fill={row.fill} />)}</Bar></BarChart></ResponsiveContainer></div></section><section className="elegex-card p-6"><p className="elegex-eyebrow">WORKLOAD SHAPE</p><h2 className="mt-2 text-lg font-semibold tracking-[-0.02em] text-[#14213D]">Task status</h2><div className="mt-4 flex h-[170px] items-center justify-center"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={taskChart} dataKey="value" nameKey="name" innerRadius={52} outerRadius={75} paddingAngle={4}>{taskChart.map((row, index) => <Cell key={row.name} fill={["#5B88F5", "#195FE6", "#EA526F", "#27A96B"][index % 4]} />)}</Pie><Tooltip contentStyle={{ borderRadius: 12, border: "1px solid #E7ECF5", fontSize: 12 }} /></PieChart></ResponsiveContainer></div><div className="grid grid-cols-2 gap-x-3 gap-y-2 text-xs">{taskChart.map((row, index) => <div key={row.name} className="flex items-center gap-2 text-[#667085]"><span className="h-2 w-2 rounded-full" style={{ background: ["#5B88F5", "#195FE6", "#EA526F", "#27A96B"][index % 4] }} />{row.name}<span className="ml-auto font-semibold text-[#24324D]">{row.value}</span></div>)}</div></section></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><section className="elegex-card overflow-hidden"><div className="flex items-center justify-between border-b border-[#EEF2F7] px-6 py-5"><div><p className="elegex-eyebrow">RECENT ACTIVITY</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">The latest movement</h2></div><Activity className="h-5 w-5 text-[#98A2B3]" /></div><div className="divide-y divide-[#F0F3F8]">{(data.activity as any[]).map(item => <div key={item.id} className="flex gap-4 px-6 py-4"><span className="mt-1 grid h-8 w-8 place-items-center rounded-xl bg-[#EEF4FF] text-[#195FE6]"><Activity className="h-4 w-4" /></span><div className="min-w-0"><p className="text-sm font-medium text-[#34435F]">{item.summary}</p><p className="mt-1 text-xs text-[#98A2B3]">{formatDistanceToNowStrict(new Date(item.createdAt), { addSuffix: true })}</p></div></div>)}</div></section><section className="elegex-card overflow-hidden"><div className="flex items-center justify-between border-b border-[#EEF2F7] px-6 py-5"><div><p className="elegex-eyebrow">UP NEXT</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">Work to protect</h2></div><CalendarClock className="h-5 w-5 text-[#98A2B3]" /></div><div className="divide-y divide-[#F0F3F8]">{(data.upcoming as any[]).map(item => <div key={item.id} className="flex items-center gap-4 px-6 py-4"><span className={`h-2 w-2 rounded-full ${item.priority === "urgent" ? "bg-[#EA526F]" : item.priority === "high" ? "bg-[#F5A524]" : "bg-[#5B88F5]"}`} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#34435F]">{item.title}</p><p className="mt-1 text-xs text-[#7A879E]">Due {stamp(item.dueDate)}</p></div><Badge className={`${statusStyles[item.status]} border-0 px-2 py-1 text-[10px] font-bold`}>{pretty(item.status)}</Badge></div>)}</div></section></div></>;
}

type RecordKind = "contacts" | "projects" | "cases";
const kindMeta: Record<RecordKind, { singular: string; title: string; description: string; icon: any; statuses: string[] }> = {
  contacts: { singular: "contact", title: "Contacts", description: "Keep relationship intelligence close to the work it informs.", icon: UsersRound, statuses: ["lead", "active", "inactive"] },
  projects: { singular: "project", title: "Projects", description: "Manage delivery programmes with a clean view of status, ownership, and momentum.", icon: FolderKanban, statuses: ["planning", "active", "on_hold", "complete", "archived"] },
  cases: { singular: "case", title: "Cases", description: "Track sensitive or exception work through a clear, accountable resolution path.", icon: BriefcaseBusiness, statuses: ["open", "investigating", "pending", "resolved", "closed"] },
};

export function RecordsPage({ kind }: { kind: RecordKind }) {
  const meta = kindMeta[kind]; const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [page, setPage] = useState(1); const [sort, setSort] = useState("updated"); const [createOpen, setCreateOpen] = useState(false); const [selected, setSelected] = useState<any>(null); const [editOpen, setEditOpen] = useState(false); const utils = trpc.useUtils();
  const operational = trpc.elegex.workspace.operationalSettings.useQuery();
  const stamp = (date?: string | Date | null) => date ? formatOrganizationDate(date, operational.data?.settings) : "No date";
  const [, setLocation] = useLocation();
  const contacts = trpc.elegex.contacts.list.useQuery({ query, status: status === "all" ? undefined : status, page, pageSize: 8 }, { enabled: kind === "contacts" });
  const projects = trpc.elegex.projects.list.useQuery({ query, status: status === "all" ? undefined : status, page, pageSize: 8 }, { enabled: kind === "projects" });
  const cases = trpc.elegex.cases.list.useQuery({ query, status: status === "all" ? undefined : status, page, pageSize: 8 }, { enabled: kind === "cases" });
  const archive = trpc.elegex.records.archive.useMutation({ onSuccess: () => { toast.success("Record archived"); void utils.elegex.invalidate(); setSelected(null); } });
  const source = kind === "contacts" ? contacts : kind === "projects" ? projects : cases; const records = ((source.data?.rows ?? []) as any[]).slice();
  records.sort((a, b) => sort === "name" ? String(a.name || a.title).localeCompare(String(b.name || b.title)) : sort === "status" ? String(a.status).localeCompare(String(b.status)) : new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
  const total = Number(source.data?.total ?? 0); const pageCount = Math.max(1, Math.ceil(total / 8)); const Icon = meta.icon;
  return <><PageHeading eyebrow="RELATIONSHIPS & DELIVERY" title={meta.title} description={meta.description} action={<Button onClick={() => setCreateOpen(true)} className="h-10 rounded-xl bg-[#195FE6] px-4 text-sm font-semibold hover:bg-[#124FC3]"><Plus className="mr-2 h-4 w-4" />New {meta.singular}</Button>} /><div className="elegex-card overflow-hidden"><div className="flex flex-col gap-3 border-b border-[#EEF2F7] p-4 lg:flex-row lg:items-center"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#98A2B3]" /><Input value={query} onChange={event => { setQuery(event.target.value); setPage(1); }} placeholder={`Search ${meta.title.toLowerCase()}`} className="h-10 border-[#E4EAF4] bg-[#FBFCFE] pl-9 text-sm shadow-none" /></div><div className="flex gap-2"><select value={status} onChange={event => { setStatus(event.target.value); setPage(1); }} className="h-10 rounded-xl border border-[#E4EAF4] bg-white px-3 text-sm text-[#50617F]"><option value="all">All statuses</option>{meta.statuses.map(option => <option key={option} value={option}>{pretty(option)}</option>)}</select><select value={sort} onChange={event => setSort(event.target.value)} className="h-10 rounded-xl border border-[#E4EAF4] bg-white px-3 text-sm text-[#50617F]"><option value="updated">Last updated</option><option value="name">Name</option><option value="status">Status</option></select></div></div>{source.isLoading ? <div className="grid min-h-80 place-items-center"><Loader2 className="h-6 w-6 animate-spin text-[#195FE6]" /></div> : records.length ? <div className="overflow-x-auto"><table className="min-w-full"><thead className="bg-[#FAFBFD]"><tr>{kind === "contacts" ? <><TableHeader label="Contact" /><TableHeader label="Organisation" /><TableHeader label="Location" /></> : kind === "projects" ? <><TableHeader label="Project" /><TableHeader label="Code" /><TableHeader label="Progress" /></> : <><TableHeader label="Case" /><TableHeader label="Severity" /><TableHeader label="Due" /></>}<TableHeader label="Status" /><th className="w-12" /></tr></thead><tbody className="divide-y divide-[#F0F3F8]">{records.map(record => <tr key={record.id} className="group cursor-pointer transition-colors hover:bg-[#FBFCFF]" onClick={() => setLocation(`/${kind}/${record.id}`)}>{kind === "contacts" ? <><TableCell><p className="font-semibold text-[#24324D]">{record.name}</p><p className="mt-1 text-xs text-[#7A879E]">{record.email || record.phone || "No contact details"}</p></TableCell><TableCell>{record.company || "—"}</TableCell><TableCell>{record.location || "—"}</TableCell></> : kind === "projects" ? <><TableCell><p className="font-semibold text-[#24324D]">{record.name}</p><p className="mt-1 max-w-xs truncate text-xs text-[#7A879E]">{record.description || "No description"}</p></TableCell><TableCell><span className="font-mono text-xs font-semibold text-[#50617F]">{record.code}</span></TableCell><TableCell><div className="flex min-w-28 items-center gap-2"><Progress value={record.progress} className="h-1.5" /><span className="text-xs font-semibold text-[#50617F]">{record.progress}%</span></div></TableCell></> : <><TableCell><p className="font-semibold text-[#24324D]">{record.title}</p><p className="mt-1 text-xs text-[#7A879E]">{record.reference}</p></TableCell><TableCell><span className={`text-xs font-semibold ${priorityStyles[record.severity]}`}>{pretty(record.severity)}</span></TableCell><TableCell className={record.dueDate && isPast(new Date(record.dueDate)) ? "text-[#D12B48]" : ""}>{stamp(record.dueDate)}</TableCell></>}<TableCell><Badge className={`${statusStyles[record.status]} border-0 px-2.5 py-1 text-[10px] font-bold`}>{pretty(record.status)}</Badge></TableCell><td className="px-5 py-4 text-right"><button onClick={event => { event.stopPropagation(); setSelected(record); }} className="rounded-lg p-1.5 text-[#98A2B3] hover:bg-[#EEF4FF] hover:text-[#195FE6]"><MoreHorizontal className="h-4 w-4" /></button></td></tr>)}</tbody></table></div> : <EmptyState icon={Icon} title={`No ${meta.title.toLowerCase()} found`} description="Adjust your filters or add the first record to this workspace." action={<Button onClick={() => setCreateOpen(true)} className="mt-4 rounded-xl bg-[#195FE6]"><Plus className="mr-2 h-4 w-4" />Add {meta.singular}</Button>} />}{total > 0 ? <div className="flex items-center justify-between border-t border-[#EEF2F7] px-5 py-4"><p className="text-xs text-[#7A879E]">Showing {records.length} of {total} records</p><div className="flex gap-2"><Button variant="outline" size="sm" disabled={page === 1} onClick={() => setPage(current => current - 1)} className="h-8 rounded-lg"><ChevronLeft className="h-4 w-4" /></Button><Button variant="outline" size="sm" disabled={page === pageCount} onClick={() => setPage(current => current + 1)} className="h-8 rounded-lg"><ChevronRight className="h-4 w-4" /></Button></div></div> : null}</div><CreateRecordDialog kind={kind} open={createOpen} onOpenChange={setCreateOpen} /><RecordDrawer kind={kind} record={selected} open={Boolean(selected)} onOpenChange={open => !open && setSelected(null)} onEdit={() => setEditOpen(true)} onArchive={() => selected && archive.mutate({ resource: kind, id: selected.id })} /><EditRecordDialog kind={kind} record={selected} open={editOpen} onOpenChange={setEditOpen} /></>;
}

export function RecordDetailPage({ kind, id }: { kind: RecordKind; id: number }) {
  const [, setLocation] = useLocation();
  const query = trpc.elegex.records.detail.useQuery({ resource: kind, id });
  const operational = trpc.elegex.workspace.operationalSettings.useQuery();
  const stamp = (date?: string | Date | null) => date ? formatOrganizationDate(date, operational.data?.settings) : "No date";
  if (query.isLoading) return <PageLoading />;
  if (!query.data) return <EmptyState icon={CircleAlert} title="Record unavailable" description="This record may have been archived or is outside your workspace scope." action={<Button onClick={() => setLocation(`/${kind}`)} className="mt-4 rounded-xl bg-[#195FE6]">Back to {kindMeta[kind].title}</Button>} />;
  const { record, relatedTasks, relatedDocuments, relatedActivity } = query.data as any;
  const title = kind === "cases" ? record.title : record.name;
  return <><button onClick={() => setLocation(`/${kind}`)} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-[#50617F] hover:text-[#195FE6]"><ChevronLeft className="h-4 w-4" />Back to {kindMeta[kind].title}</button><PageHeading eyebrow={`${kindMeta[kind].singular.toUpperCase()} DETAIL`} title={title} description={kind === "projects" ? record.description || "No description provided for this project." : kind === "cases" ? record.summary || "No case summary provided." : `${record.company || "Independent contact"} · ${record.email || record.phone || "No direct contact information"}`} /><div className="grid gap-5 xl:grid-cols-[1.25fr_0.75fr]"><section className="space-y-5"><div className="elegex-card p-6"><div className="flex flex-wrap items-center gap-3"><Badge className={`${statusStyles[record.status]} border-0 px-3 py-1`}>{pretty(record.status)}</Badge>{kind === "projects" ? <span className={`text-sm font-semibold ${priorityStyles[record.priority]}`}>{pretty(record.priority)} priority</span> : null}{kind === "cases" ? <span className={`text-sm font-semibold ${priorityStyles[record.severity]}`}>{pretty(record.severity)} severity</span> : null}</div><div className="mt-6 grid gap-5 sm:grid-cols-3"><Info label={kind === "projects" ? "Project code" : kind === "cases" ? "Reference" : "Organisation"} value={kind === "projects" ? record.code : kind === "cases" ? record.reference : record.company || "—"} /><Info label="Created" value={stamp(record.createdAt)} /><Info label="Last updated" value={stamp(record.updatedAt)} /></div>{kind === "projects" ? <div className="mt-6"><div className="mb-2 flex justify-between text-sm"><span className="font-semibold text-[#34435F]">Delivery progress</span><span className="font-semibold text-[#195FE6]">{record.progress}%</span></div><Progress value={record.progress} className="h-2" /></div> : null}</div>{kind === "projects" ? <section className="elegex-card overflow-hidden"><div className="border-b border-[#EEF2F7] px-6 py-5"><p className="elegex-eyebrow">LINKED TASKS</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">Work delivery</h2></div>{relatedTasks.length ? <div className="divide-y divide-[#F0F3F8]">{relatedTasks.map((task: any) => <div key={task.id} className="flex items-center justify-between gap-3 px-6 py-4"><div><p className="text-sm font-semibold text-[#34435F]">{task.title}</p><p className="mt-1 text-xs text-[#7A879E]">Due {stamp(task.dueDate)}</p></div><Badge className={`${statusStyles[task.status]} border-0 text-[10px]`}>{pretty(task.status)}</Badge></div>)}</div> : <EmptyState icon={CheckSquare} title="No linked tasks" description="Tasks associated with this project will appear here." />}</section> : null}</section><aside className="space-y-5"><section className="elegex-card overflow-hidden"><div className="border-b border-[#EEF2F7] px-5 py-4"><p className="elegex-eyebrow">RELATED DOCUMENTS</p></div>{relatedDocuments.length ? <div className="divide-y divide-[#F0F3F8]">{relatedDocuments.map((document: any) => document.health === "unavailable" ? <div key={document.id} className="flex items-center gap-3 px-5 py-4 text-[#98A2B3]"><FileArchive className="h-4 w-4" /><span className="min-w-0 flex-1 truncate text-sm font-medium">{document.fileName}</span><span className="text-[10px] font-bold tracking-wide">UNAVAILABLE</span></div> : <a href={document.storageUrl} key={document.id} target="_blank" rel="noreferrer" className="flex items-center gap-3 px-5 py-4 hover:bg-[#FBFCFF]"><FileText className="h-4 w-4 text-[#195FE6]" /><span className="min-w-0 flex-1 truncate text-sm font-medium text-[#34435F]">{document.fileName}</span><ArrowUpRight className="h-4 w-4 text-[#98A2B3]" /></a>)}</div> : <div className="px-5 py-6 text-sm leading-6 text-[#7A879E]">No documents are attached to this {kindMeta[kind].singular}.</div>}</section><section className="elegex-card overflow-hidden"><div className="border-b border-[#EEF2F7] px-5 py-4"><p className="elegex-eyebrow">RECORD ACTIVITY</p></div>{relatedActivity.length ? <div className="divide-y divide-[#F0F3F8]">{relatedActivity.map((item: any) => <div key={item.id} className="px-5 py-4"><p className="text-sm font-medium text-[#34435F]">{item.summary}</p><p className="mt-1 text-xs text-[#98A2B3]">{formatDistanceToNowStrict(new Date(item.createdAt), { addSuffix: true })}</p></div>)}</div> : <div className="px-5 py-6 text-sm leading-6 text-[#7A879E]">No scoped activity has been recorded yet.</div>}</section></aside></div></>;
}

function TableHeader({ label }: { label: string }) { return <th className="px-5 py-3 text-left text-[10px] font-bold tracking-[0.14em] text-[#7A879E]">{label}</th>; }
function TableCell({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <td className={`px-5 py-4 text-sm text-[#50617F] ${className}`}>{children}</td>; }

function CreateRecordDialog({ kind, open, onOpenChange }: { kind: RecordKind; open: boolean; onOpenChange: (open: boolean) => void }) {
  const utils = trpc.useUtils(); const [form, setForm] = useState<any>({ status: kind === "contacts" ? "lead" : kind === "projects" ? "planning" : "open", priority: "medium", severity: "medium" }); const set = (key: string, value: string) => setForm((current: any) => ({ ...current, [key]: value }));
  const onSuccess = () => { toast.success(`${kindMeta[kind].singular[0].toUpperCase()}${kindMeta[kind].singular.slice(1)} created`); void utils.elegex.invalidate(); onOpenChange(false); setForm({}); };
  const contact = trpc.elegex.contacts.create.useMutation({ onSuccess }); const project = trpc.elegex.projects.create.useMutation({ onSuccess }); const caseMutation = trpc.elegex.cases.create.useMutation({ onSuccess }); const pending = contact.isPending || project.isPending || caseMutation.isPending;
  const submit = () => { if (kind === "contacts") { if (!form.name) return toast.error("A contact name is required"); contact.mutate(form); } else if (kind === "projects") { if (!form.name || !form.code) return toast.error("Project name and code are required"); project.mutate({ ...form, budget: form.budget ? Number(form.budget) : undefined }); } else { if (!form.title || !form.reference) return toast.error("Case title and reference are required"); caseMutation.mutate(form); } };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-lg rounded-2xl border-[#E4EAF4] p-0"><DialogHeader className="border-b border-[#EEF2F7] px-6 py-5"><DialogTitle className="text-xl font-semibold text-[#14213D]">New {kindMeta[kind].singular}</DialogTitle><DialogDescription>Capture the essential context now; it can be enriched as the work develops.</DialogDescription></DialogHeader><div className="grid gap-4 px-6 py-5">{kind === "contacts" ? <><Field label="Full name" value={form.name} onChange={value => set("name", value)} placeholder="e.g. Aisha Naidoo" /><Field label="Organisation" value={form.company} onChange={value => set("company", value)} placeholder="e.g. Northstar Properties" /><div className="grid gap-4 sm:grid-cols-2"><Field label="Email" value={form.email} onChange={value => set("email", value)} placeholder="name@company.com" /><Field label="Phone" value={form.phone} onChange={value => set("phone", value)} placeholder="+27 11 555 0000" /></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Location" value={form.location} onChange={value => set("location", value)} placeholder="City or region" /><NativeSelect label="Relationship status" value={form.status || "lead"} onChange={value => set("status", value)} options={["lead", "active", "inactive"]} /></div></> : kind === "projects" ? <><div className="grid gap-4 sm:grid-cols-[1fr_0.45fr]"><Field label="Project name" value={form.name} onChange={value => set("name", value)} placeholder="e.g. Cedar Digital Intake" /><Field label="Project code" value={form.code} onChange={value => set("code", value)} placeholder="CD-118" /></div><Field label="Description" value={form.description} onChange={value => set("description", value)} placeholder="What does successful delivery look like?" multiline /><div className="grid gap-4 sm:grid-cols-2"><NativeSelect label="Status" value={form.status || "planning"} onChange={value => set("status", value)} options={["planning", "active", "on_hold", "complete"]} /><NativeSelect label="Priority" value={form.priority || "medium"} onChange={value => set("priority", value)} options={["low", "medium", "high", "urgent"]} /></div><Field label="Budget (ZAR)" value={form.budget} onChange={value => set("budget", value)} placeholder="e.g. 240000" type="number" /></> : <><div className="grid gap-4 sm:grid-cols-[0.6fr_1fr]"><Field label="Reference" value={form.reference} onChange={value => set("reference", value)} placeholder="CS-2044" /><Field label="Case title" value={form.title} onChange={value => set("title", value)} placeholder="Clear, concise case title" /></div><Field label="Summary" value={form.summary} onChange={value => set("summary", value)} placeholder="Describe the issue, context, and impact." multiline /><NativeSelect label="Severity" value={form.severity || "medium"} onChange={value => set("severity", value)} options={["low", "medium", "high", "critical"]} /></>}</div><div className="flex justify-end gap-3 border-t border-[#EEF2F7] px-6 py-4"><Button variant="outline" onClick={() => onOpenChange(false)} className="rounded-xl">Cancel</Button><Button disabled={pending} onClick={submit} className="rounded-xl bg-[#195FE6] hover:bg-[#124FC3]">{pending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="mr-2 h-4 w-4" />}Create {kindMeta[kind].singular}</Button></div></DialogContent></Dialog>;
}

function EditRecordDialog({ kind, record, open, onOpenChange }: { kind: RecordKind; record: any; open: boolean; onOpenChange: (open: boolean) => void }) {
  const utils = trpc.useUtils(); const [name, setName] = useState(""); const [status, setStatus] = useState(""); const [progress, setProgress] = useState("");
  const contact = trpc.elegex.contacts.update.useMutation({ onSuccess: () => { toast.success("Contact updated"); void utils.elegex.invalidate(); onOpenChange(false); } }); const project = trpc.elegex.projects.update.useMutation({ onSuccess: () => { toast.success("Project updated"); void utils.elegex.invalidate(); onOpenChange(false); } }); const caseMutation = trpc.elegex.cases.update.useMutation({ onSuccess: () => { toast.success("Case updated"); void utils.elegex.invalidate(); onOpenChange(false); } });
  if (!record) return null;
  const initialName = name || (kind === "contacts" ? record.name : record.name); const initialStatus = status || record.status; const pending = contact.isPending || project.isPending;
  const submit = () => kind === "contacts" ? contact.mutate({ id: record.id, name: initialName, status: initialStatus as any }) : kind === "projects" ? project.mutate({ id: record.id, name: initialName, status: initialStatus as any, progress: progress ? Number(progress) : record.progress }) : caseMutation.mutate({ id: record.id, title: initialName, status: initialStatus as any });
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-md rounded-2xl"><DialogHeader><DialogTitle>Update {kindMeta[kind].singular}</DialogTitle><DialogDescription>Changes are recorded in the workspace activity log.</DialogDescription></DialogHeader><div className="grid gap-4"><Field label={kind === "contacts" ? "Contact name" : kind === "projects" ? "Project name" : "Case title"} value={initialName} onChange={setName} /><NativeSelect label="Status" value={initialStatus} onChange={setStatus} options={kindMeta[kind].statuses} />{kind === "projects" ? <Field label="Progress (%)" type="number" value={progress || String(record.progress)} onChange={setProgress} /> : null}</div><div className="flex justify-end gap-3"><Button variant="outline" onClick={() => onOpenChange(false)} className="rounded-xl">Cancel</Button><Button disabled={pending || caseMutation.isPending} onClick={submit} className="rounded-xl bg-[#195FE6]">Save changes</Button></div></DialogContent></Dialog>;
}

function RecordDrawer({ kind, record, open, onOpenChange, onEdit, onArchive }: { kind: RecordKind; record: any; open: boolean; onOpenChange: (open: boolean) => void; onEdit: () => void; onArchive: () => void }) { if (!record) return null; const title = kind === "contacts" ? record.name : kind === "projects" ? record.name : record.title; return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-w-xl rounded-2xl border-[#E4EAF4] p-0"><div className="border-b border-[#EEF2F7] px-6 py-6"><div className="flex items-start justify-between gap-5"><div><p className="elegex-eyebrow">{kind === "cases" ? record.reference : kindMeta[kind].singular}</p><DialogTitle className="mt-2 text-2xl font-semibold tracking-[-0.04em] text-[#14213D]">{title}</DialogTitle><Badge className={`mt-3 border-0 ${statusStyles[record.status]}`}>{pretty(record.status)}</Badge></div><button onClick={() => onOpenChange(false)} className="rounded-lg p-1 text-[#98A2B3]"><X className="h-5 w-5" /></button></div></div><div className="grid gap-5 px-6 py-6 sm:grid-cols-2"><Info label={kind === "contacts" ? "Organisation" : kind === "projects" ? "Project code" : "Severity"} value={kind === "contacts" ? record.company : kind === "projects" ? record.code : pretty(record.severity)} /><Info label={kind === "contacts" ? "Contact details" : "Last updated"} value={kind === "contacts" ? record.email || record.phone || "No contact details" : stamp(record.updatedAt)} />{kind === "projects" ? <><Info label="Budget" value={compactMoney(record.budget)} /><Info label="Progress" value={`${record.progress}%`} /></> : null}{kind === "cases" ? <><Info label="Due date" value={stamp(record.dueDate)} /><Info label="Summary" value={record.summary || "No summary supplied"} /></> : null}</div><div className="flex justify-between border-t border-[#EEF2F7] px-6 py-4"><Button variant="ghost" onClick={onArchive} className="rounded-xl text-[#C63550] hover:bg-[#FFF0F2] hover:text-[#C63550]"><Trash2 className="mr-2 h-4 w-4" />Archive</Button><Button onClick={onEdit} className="rounded-xl bg-[#195FE6] hover:bg-[#124FC3]"><Pencil className="mr-2 h-4 w-4" />Edit record</Button></div></DialogContent></Dialog>; }
function Info({ label, value }: { label: string; value: string }) { return <div><p className="elegex-eyebrow">{label}</p><p className="mt-2 text-sm font-medium leading-6 text-[#34435F]">{value}</p></div>; }
function Field({ label, value, onChange, placeholder, type = "text", multiline = false }: { label: string; value?: string; onChange: (value: string) => void; placeholder?: string; type?: string; multiline?: boolean }) { const managed = label === "Primary colour"; return <div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">{label}{managed ? " (managed)" : ""}</Label>{multiline ? <Textarea value={value || ""} onChange={event => onChange(event.target.value)} placeholder={placeholder} className="min-h-24 border-[#DFE7F3] text-sm" /> : <Input type={type} value={value || ""} onChange={event => onChange(event.target.value)} placeholder={placeholder} readOnly={managed} className="h-10 border-[#DFE7F3] text-sm read-only:bg-[#F5F7FB] read-only:text-[#7A879E]" />}</div>; }
function NativeSelect({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) { const managed = label === "Timezone"; return <div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">{label}{managed ? " (managed)" : ""}</Label><select value={value} onChange={event => onChange(event.target.value)} disabled={managed} className="h-10 rounded-md border border-[#DFE7F3] bg-white px-3 text-sm text-[#34435F] disabled:cursor-not-allowed disabled:bg-[#F5F7FB] disabled:text-[#7A879E]">{options.map(option => <option key={option} value={option}>{pretty(option)}</option>)}</select></div>; }

export function TasksPage() {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [createOpen, setCreateOpen] = useState(false); const [selected, setSelected] = useState<any>(null); const tasks = trpc.elegex.tasks.list.useQuery({ query, status: status === "all" ? undefined : status, page: 1, pageSize: 30 }); const operational = trpc.elegex.workspace.operationalSettings.useQuery(); const stamp = (date?: string | Date | null) => date ? formatOrganizationDate(date, operational.data?.settings) : "No date"; const utils = trpc.useUtils(); const update = trpc.elegex.tasks.update.useMutation({ onSuccess: () => { toast.success("Task updated"); void utils.elegex.invalidate(); } });
  return <><PageHeading eyebrow="WORK MANAGEMENT" title="Tasks" description="A clear delivery queue for the work that needs a named owner and a visible next step." action={<Button onClick={() => setCreateOpen(true)} className="h-10 rounded-xl bg-[#195FE6] hover:bg-[#124FC3]"><Plus className="mr-2 h-4 w-4" />New task</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#98A2B3]" /><Input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search tasks" className="h-10 border-[#DFE7F3] bg-white pl-9" /></div><select value={status} onChange={event => setStatus(event.target.value)} className="h-10 rounded-xl border border-[#DFE7F3] bg-white px-3 text-sm text-[#50617F]"><option value="all">All statuses</option>{["todo", "in_progress", "blocked", "complete"].map(option => <option key={option} value={option}>{pretty(option)}</option>)}</select></div><div className="grid gap-3 lg:grid-cols-2">{(tasks.data?.rows as any[] || []).map(task => <div key={task.id} className="elegex-card flex flex-col gap-4 p-5 sm:flex-row sm:items-start"><button onClick={() => update.mutate({ id: task.id, status: task.status === "complete" ? "todo" : "complete" })} className={`mt-0.5 grid h-5 w-5 shrink-0 place-items-center rounded-full border ${task.status === "complete" ? "border-[#27A96B] bg-[#27A96B] text-white" : "border-[#C8D3E5] bg-white text-transparent"}`}><Check className="h-3.5 w-3.5" /></button><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className={`font-semibold text-[#24324D] ${task.status === "complete" ? "line-through opacity-60" : ""}`}>{task.title}</p><Badge className={`${statusStyles[task.status]} border-0 px-2 py-0.5 text-[10px] font-bold`}>{pretty(task.status)}</Badge></div><p className="mt-2 text-sm leading-6 text-[#667085]">{task.description || "No description provided"}</p><div className="mt-4 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs"><span className={`${task.dueDate && isPast(new Date(task.dueDate)) && task.status !== "complete" ? "font-semibold text-[#D12B48]" : "text-[#7A879E]"}`}><Clock3 className="mr-1 inline h-3.5 w-3.5" />Due {stamp(task.dueDate)}</span><span className={`font-semibold ${priorityStyles[task.priority]}`}>{pretty(task.priority)} priority</span><button onClick={() => setSelected(task)} className="ml-auto inline-flex items-center gap-1 font-semibold text-[#195FE6]"><Pencil className="h-3.5 w-3.5" />Edit</button></div></div></div>)}</div><CreateTaskDialog open={createOpen} onOpenChange={setCreateOpen} /><TaskEditDialog task={selected} onOpenChange={open => !open && setSelected(null)} /></>;
}

function CreateTaskDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) { const [form, setForm] = useState({ title: "", description: "", priority: "medium", projectId: "", assigneeId: "", dueDate: "" }); const utils = trpc.useUtils(); const projects = trpc.elegex.projects.list.useQuery({ page: 1, pageSize: 50 }); const members = trpc.elegex.workspace.members.useQuery(); const mutation = trpc.elegex.tasks.create.useMutation({ onSuccess: () => { toast.success("Task created and assignee notified"); void utils.elegex.invalidate(); onOpenChange(false); setForm({ title: "", description: "", priority: "medium", projectId: "", assigneeId: "", dueDate: "" }); } }); return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>New task</DialogTitle><DialogDescription>Give the work a clear outcome, an accountable owner, and a delivery context.</DialogDescription></DialogHeader><div className="grid gap-4"><Field label="Task title" value={form.title} onChange={title => setForm(current => ({ ...current, title }))} placeholder="What needs to happen?" /><Field label="Description" multiline value={form.description} onChange={description => setForm(current => ({ ...current, description }))} placeholder="Add useful delivery context." /><div className="grid gap-4 sm:grid-cols-2"><NativeSelect label="Priority" value={form.priority} onChange={priority => setForm(current => ({ ...current, priority }))} options={["low", "medium", "high", "urgent"]} /><div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">Linked project</Label><select value={form.projectId} onChange={event => setForm(current => ({ ...current, projectId: event.target.value }))} className="h-10 rounded-md border border-[#DFE7F3] bg-white px-3 text-sm text-[#34435F]"><option value="">No linked project</option>{((projects.data?.rows || []) as any[]).map(project => <option key={project.id} value={project.id}>{project.code} · {project.name}</option>)}</select></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">Assignee</Label><select value={form.assigneeId} onChange={event => setForm(current => ({ ...current, assigneeId: event.target.value }))} className="h-10 rounded-md border border-[#DFE7F3] bg-white px-3 text-sm text-[#34435F]"><option value="">Unassigned</option>{(members.data || []).map((member: any) => <option key={member.id} value={member.id}>{member.name || member.email} · {pretty(member.role)}</option>)}</select></div><Field label="Due date" type="date" value={form.dueDate} onChange={dueDate => setForm(current => ({ ...current, dueDate }))} /></div></div><div className="flex justify-end gap-3"><Button variant="outline" onClick={() => onOpenChange(false)} className="rounded-xl">Cancel</Button><Button onClick={() => form.title ? mutation.mutate({ title: form.title, description: form.description || undefined, priority: form.priority as any, projectId: form.projectId ? Number(form.projectId) : undefined, assigneeId: form.assigneeId ? Number(form.assigneeId) : undefined, dueDate: form.dueDate ? new Date(`${form.dueDate}T12:00:00`) : undefined }) : toast.error("A task title is required")} disabled={mutation.isPending} className="rounded-xl bg-[#195FE6]">Create task</Button></div></DialogContent></Dialog>; }

function TaskEditDialog({ task, onOpenChange }: { task: any; onOpenChange: (open: boolean) => void }) { const utils = trpc.useUtils(); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [dueDate, setDueDate] = useState(""); const [taskStatus, setTaskStatus] = useState(""); const [priority, setPriority] = useState(""); const [projectId, setProjectId] = useState(""); const [assigneeId, setAssigneeId] = useState(""); const projects = trpc.elegex.projects.list.useQuery({ page: 1, pageSize: 50 }); const members = trpc.elegex.workspace.members.useQuery(); const update = trpc.elegex.tasks.update.useMutation({ onSuccess: () => { toast.success("Task details saved"); void utils.elegex.invalidate(); onOpenChange(false); } }); const archive = trpc.elegex.records.archive.useMutation({ onSuccess: () => { toast.success("Task archived"); void utils.elegex.invalidate(); onOpenChange(false); } }); if (!task) return null; const normalizedDate = dueDate || (task.dueDate ? format(new Date(task.dueDate), "yyyy-MM-dd") : ""); return <Dialog open={Boolean(task)} onOpenChange={onOpenChange}><DialogContent className="max-w-xl rounded-2xl"><DialogHeader><DialogTitle>Edit task</DialogTitle><DialogDescription>Refine its content, accountability, delivery state, and due date. Changes are logged in the workspace.</DialogDescription></DialogHeader><div className="grid gap-4"><Field label="Task title" value={title || task.title} onChange={setTitle} /><Field label="Description" multiline value={description || task.description || ""} onChange={setDescription} /><div className="grid gap-4 sm:grid-cols-2"><NativeSelect label="Status" value={taskStatus || task.status} onChange={setTaskStatus} options={["todo", "in_progress", "blocked", "complete"]} /><NativeSelect label="Priority" value={priority || task.priority} onChange={setPriority} options={["low", "medium", "high", "urgent"]} /></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">Linked project</Label><select value={projectId || String(task.projectId || "")} onChange={event => setProjectId(event.target.value)} className="h-10 rounded-md border border-[#DFE7F3] bg-white px-3 text-sm text-[#34435F]"><option value="">No linked project</option>{((projects.data?.rows || []) as any[]).map(project => <option key={project.id} value={project.id}>{project.code} · {project.name}</option>)}</select></div><div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">Assignee</Label><select value={assigneeId || String(task.assigneeId || "")} onChange={event => setAssigneeId(event.target.value)} className="h-10 rounded-md border border-[#DFE7F3] bg-white px-3 text-sm text-[#34435F]"><option value="">Unassigned</option>{(members.data || []).map((member: any) => <option key={member.id} value={member.id}>{member.name || member.email} · {pretty(member.role)}</option>)}</select></div></div><Field label="Due date" type="date" value={normalizedDate} onChange={setDueDate} /></div><div className="flex items-center justify-between"><Button variant="ghost" onClick={() => archive.mutate({ resource: "tasks", id: task.id })} className="rounded-xl text-[#C63550] hover:bg-[#FFF0F2] hover:text-[#C63550]"><Trash2 className="mr-2 h-4 w-4" />Archive</Button><div className="flex gap-3"><Button variant="outline" onClick={() => onOpenChange(false)} className="rounded-xl">Cancel</Button><Button onClick={() => update.mutate({ id: task.id, title: title || task.title, description: description || task.description || undefined, status: (taskStatus || task.status) as any, priority: (priority || task.priority) as any, projectId: projectId ? Number(projectId) : undefined, assigneeId: assigneeId ? Number(assigneeId) : undefined, dueDate: normalizedDate ? new Date(`${normalizedDate}T12:00:00`) : undefined })} className="rounded-xl bg-[#195FE6]">Save task</Button></div></div></DialogContent></Dialog>; }

export function DocumentsPage() { const [resource, setResource] = useState<"all" | "project" | "contact" | "case">("all"); const [recordId, setRecordId] = useState(""); const projects = trpc.elegex.projects.list.useQuery({ page: 1, pageSize: 50 }); const contacts = trpc.elegex.contacts.list.useQuery({ page: 1, pageSize: 50 }); const cases = trpc.elegex.cases.list.useQuery({ page: 1, pageSize: 50 }); const documents = trpc.elegex.documents.list.useQuery(resource === "all" ? undefined : { resource, recordId: recordId ? Number(recordId) : undefined }); const utils = trpc.useUtils(); const upload = trpc.elegex.documents.upload.useMutation({ onSuccess: () => { toast.success("Document uploaded to the selected record"); void utils.elegex.documents.invalidate(); }, onError: error => toast.error(error.message) }); const records = resource === "project" ? projects.data?.rows || [] : resource === "contact" ? contacts.data?.rows || [] : cases.data?.rows || []; const handleFile = (file?: File) => { if (!file) return; if (file.size > 5_000_000) return toast.error("Files must be 5 MB or smaller"); if (!file.type) return toast.error("Choose a supported PDF, document, image, CSV, or text file"); const reader = new FileReader(); reader.onerror = () => toast.error("The selected file could not be read"); reader.onload = () => upload.mutate({ fileName: file.name, mimeType: file.type, dataUrl: String(reader.result), ...(resource === "project" && recordId ? { projectId: Number(recordId) } : {}), ...(resource === "contact" && recordId ? { contactId: Number(recordId) } : {}), ...(resource === "case" && recordId ? { caseId: Number(recordId) } : {}) }); reader.readAsDataURL(file); }; return <><PageHeading eyebrow="DOCUMENT CONTROL" title="Documents" description="Attach working evidence to the exact contact, project, or case it supports." action={<label className="inline-flex h-10 items-center rounded-xl bg-[#195FE6] px-4 text-sm font-semibold text-white hover:bg-[#124FC3]"><UploadCloud className="mr-2 h-4 w-4" />Upload document<input type="file" className="hidden" accept=".pdf,.txt,.csv,.docx,.png,.jpg,.jpeg" onChange={event => handleFile(event.target.files?.[0])} /></label>} /><div className="elegex-card mb-5 grid gap-3 p-4 sm:grid-cols-2"><div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">Record type</Label><select value={resource} onChange={event => { setResource(event.target.value as any); setRecordId(""); }} className="h-10 rounded-xl border border-[#DFE7F3] bg-white px-3 text-sm text-[#34435F]"><option value="all">All workspace documents</option><option value="project">Project</option><option value="contact">Contact</option><option value="case">Case</option></select></div><div className="grid gap-2"><Label className="text-xs font-semibold text-[#50617F]">Attached record</Label><select disabled={resource === "all"} value={recordId} onChange={event => setRecordId(event.target.value)} className="h-10 rounded-xl border border-[#DFE7F3] bg-white px-3 text-sm text-[#34435F] disabled:bg-[#F5F7FB]"><option value="">{resource === "all" ? "Choose a record type first" : `All ${resource} documents`}</option>{(records as any[]).map(record => <option key={record.id} value={record.id}>{record.name || record.title} {record.code ? `· ${record.code}` : record.reference ? `· ${record.reference}` : ""}</option>)}</select></div></div>{upload.isPending ? <div className="mb-4 flex items-center gap-2 rounded-xl bg-[#EAF1FF] px-4 py-3 text-sm text-[#195FE6]"><Loader2 className="h-4 w-4 animate-spin" />Securely uploading your document…</div> : null}<div className="elegex-card overflow-hidden">{documents.data?.length ? <div className="divide-y divide-[#EEF2F7]">{documents.data.map((document: any) => <div key={document.id} className="flex items-center gap-4 px-5 py-4"><span className={`grid h-10 w-10 place-items-center rounded-xl ${document.health === "unavailable" ? "bg-[#F5F7FB] text-[#98A2B3]" : "bg-[#EEF4FF] text-[#195FE6]"}`}><FileText className="h-5 w-5" /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#34435F]">{document.fileName}</p><p className="mt-1 text-xs text-[#7A879E]">{document.mimeType} · {(document.sizeBytes / 1024).toFixed(0)} KB · Added {stamp(document.createdAt)}{document.health === "unavailable" ? " · File unavailable" : ""}</p></div>{document.health === "unavailable" ? <span className="rounded-xl border border-[#E4EAF4] p-2 text-[#98A2B3]" title="This document is no longer available"><FileArchive className="h-4 w-4" /></span> : <a href={document.storageUrl} target="_blank" rel="noreferrer" className="rounded-xl border border-[#DFE7F3] p-2 text-[#50617F] hover:border-[#B6D4FF] hover:text-[#195FE6]" aria-label={`Download ${document.fileName}`}><ArrowDownToLine className="h-4 w-4" /></a>}</div>)}</div> : <EmptyState icon={FileArchive} title="No documents in this view" description="Upload a PDF, office document, image, CSV, or text file and attach it to the selected record." />}</div></>;
}

export function ReportsPage() { const rows = trpc.elegex.reports.rows.useQuery(); const views = trpc.elegex.reports.savedViews.useQuery(); const utils = trpc.useUtils(); const [statusFilter, setStatusFilter] = useState("all"); const [priorityFilter, setPriorityFilter] = useState("all"); const saveView = trpc.elegex.reports.saveView.useMutation({ onSuccess: () => { toast.success("Report view saved"); void utils.elegex.reports.savedViews.invalidate(); } }); const activeRows = ((rows.data || []) as any[]).filter(row => (statusFilter === "all" || row.status === statusFilter) && (priorityFilter === "all" || row.priority === priorityFilter)); const exportCsv = () => { const header = ["Project code", "Project", "Status", "Priority", "Progress", "Due date", "Budget", "Contact"]; const lines = activeRows.map((row: any) => [row.code, row.project, row.status, row.priority, row.progress, row.dueDate ? format(new Date(row.dueDate), "yyyy-MM-dd") : "", row.budget || "", row.contact || ""].map(value => `"${String(value).replaceAll('"', '""')}"`).join(",")); const blob = new Blob([[header.join(","), ...lines].join("\n")], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "elegex-project-report.csv"; anchor.click(); URL.revokeObjectURL(url); toast.success("Filtered CSV export downloaded"); }; const handleSave = () => { const name = window.prompt("Name this report view"); if (name) saveView.mutate({ name, filters: { dataset: "projects", status: statusFilter, priority: priorityFilter } }); }; const applyView = (view: any) => { const filters = view.filters as any; if (filters?.status) setStatusFilter(filters.status); if (filters?.priority) setPriorityFilter(filters.priority); toast.success(`Applied ${view.name}`); }; return <><PageHeading eyebrow="REPORTING & INSIGHTS" title="Reports" description="Use portfolio data to create a more measured view of delivery capacity and programme risk." action={<div className="flex gap-2"><Button variant="outline" onClick={handleSave} className="h-10 rounded-xl"><ListFilter className="mr-2 h-4 w-4" />Save view</Button><Button onClick={exportCsv} className="h-10 rounded-xl bg-[#195FE6] hover:bg-[#124FC3]"><Download className="mr-2 h-4 w-4" />Export CSV</Button></div>} /><div className="grid gap-5 xl:grid-cols-[0.7fr_1.3fr]"><section className="elegex-card p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#EAF1FF] text-[#195FE6]"><ListFilter className="h-5 w-5" /></span><div><p className="elegex-eyebrow">SAVED VIEWS</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">Reusable focus areas</h2></div></div><div className="mt-5 space-y-2">{(views.data || []).map((view: any) => <button onClick={() => applyView(view)} key={view.id} className="w-full rounded-xl border border-[#EEF2F7] p-3 text-left hover:border-[#B6D4FF] hover:bg-[#FBFDFF]"><p className="text-sm font-semibold text-[#34435F]">{view.name}</p><p className="mt-1 text-xs text-[#7A879E]">{pretty(view.resource)} · {view.isShared ? "Shared with workspace" : "Private"}</p></button>)}</div></section><section className="elegex-card overflow-hidden"><div className="border-b border-[#EEF2F7] px-6 py-5"><div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-center"><div><p className="elegex-eyebrow">PROJECT DELIVERY</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">Current portfolio export</h2></div><div className="flex gap-2"><select value={statusFilter} onChange={event => setStatusFilter(event.target.value)} className="h-9 rounded-lg border border-[#DFE7F3] bg-white px-2 text-xs text-[#50617F]"><option value="all">All statuses</option>{["planning", "active", "on_hold", "complete", "archived"].map(value => <option key={value} value={value}>{pretty(value)}</option>)}</select><select value={priorityFilter} onChange={event => setPriorityFilter(event.target.value)} className="h-9 rounded-lg border border-[#DFE7F3] bg-white px-2 text-xs text-[#50617F]"><option value="all">All priorities</option>{["low", "medium", "high", "urgent"].map(value => <option key={value} value={value}>{pretty(value)}</option>)}</select></div></div></div><div className="overflow-x-auto"><table className="min-w-full"><thead className="bg-[#FAFBFD]"><tr>{["Project", "Status", "Priority", "Progress", "Budget"].map(label => <TableHeader key={label} label={label} />)}</tr></thead><tbody className="divide-y divide-[#F0F3F8]">{activeRows.map((row: any) => <tr key={row.code}><TableCell><p className="font-semibold text-[#24324D]">{row.project}</p><p className="mt-1 font-mono text-[11px] text-[#7A879E]">{row.code}</p></TableCell><TableCell><Badge className={`${statusStyles[row.status]} border-0 text-[10px]`}>{pretty(row.status)}</Badge></TableCell><TableCell><span className={`text-xs font-semibold ${priorityStyles[row.priority]}`}>{pretty(row.priority)}</span></TableCell><TableCell><div className="flex items-center gap-2"><Progress value={row.progress} className="h-1.5 min-w-16" /><span className="text-xs text-[#50617F]">{row.progress}%</span></div></TableCell><TableCell>{compactMoney(row.budget)}</TableCell></tr>)}</tbody></table>{!activeRows.length ? <div className="px-6 py-10 text-center text-sm text-[#7A879E]">No portfolio records match these filters.</div> : null}</div></section></div></>;
}

export function NotificationsPage() { const data = trpc.elegex.notifications.list.useQuery(); const utils = trpc.useUtils(); const markRead = trpc.elegex.notifications.markRead.useMutation({ onSuccess: () => void utils.elegex.invalidate() }); return <><PageHeading eyebrow="WORKSPACE SIGNALS" title="Notifications" description="Assignments, important activity, and workspace updates are gathered here." /><section className="elegex-card overflow-hidden">{data.data?.length ? <div className="divide-y divide-[#EEF2F7]">{data.data.map((notification: any) => <button key={notification.id} onClick={() => !notification.readAt && markRead.mutate({ id: notification.id })} className={`flex w-full gap-4 px-6 py-5 text-left ${notification.readAt ? "bg-white" : "bg-[#FBFDFF]"}`}><span className={`mt-0.5 grid h-9 w-9 place-items-center rounded-xl ${notification.type === "assignment" ? "bg-[#EAF1FF] text-[#195FE6]" : notification.type === "system" ? "bg-[#E8F8EF] text-[#198754]" : "bg-[#FFF4D6] text-[#B66700]"}`}>{notification.type === "assignment" ? <CheckCircle2 className="h-4 w-4" /> : notification.type === "system" ? <Sparkles className="h-4 w-4" /> : <Activity className="h-4 w-4" />}</span><span className="min-w-0 flex-1"><span className="flex items-center gap-2"><span className="text-sm font-semibold text-[#34435F]">{notification.title}</span>{!notification.readAt ? <span className="h-2 w-2 rounded-full bg-[#195FE6]" /> : null}</span><span className="mt-1 block text-sm leading-6 text-[#667085]">{notification.description}</span><span className="mt-2 block text-xs text-[#98A2B3]">{formatDistanceToNowStrict(new Date(notification.createdAt), { addSuffix: true })}</span></span></button>)}</div> : <EmptyState icon={Bell} title="All caught up" description="New assignments and workspace signals will appear here." />}</section></>;
}

export function AdminPage({ settingsOnly = false }: { settingsOnly?: boolean }) { const workspace = trpc.elegex.workspace.current.useQuery(); const admin = trpc.elegex.admin.data.useQuery(undefined, { enabled: workspace.data?.role === "owner" || workspace.data?.role === "admin" }); const utils = trpc.useUtils(); const updateRole = trpc.elegex.admin.updateMemberRole.useMutation({ onSuccess: () => { toast.success("Role updated"); void utils.elegex.invalidate(); } }); const reset = trpc.elegex.admin.resetDemo.useMutation({ onSuccess: () => { toast.success("Six-month synthetic demo data restored"); void utils.elegex.invalidate(); } }); const updateSettings = trpc.elegex.admin.updateSettings.useMutation({ onSuccess: () => { toast.success("Workspace settings saved"); void utils.elegex.invalidate(); } }); const [workspaceName, setWorkspaceName] = useState(""); const permitted = workspace.data?.role === "owner" || workspace.data?.role === "admin"; if (workspace.isLoading) return <PageLoading />; if (!permitted) return <Forbidden />;
  return <>{settingsOnly ? <PageHeading eyebrow="WORKSPACE CONFIGURATION" title="Settings" description="Control your workspace identity and a small set of team preferences." /> : <PageHeading eyebrow="WORKSPACE ADMINISTRATION" title="Administration" description="Manage membership, roles, audit visibility, and the unified synthetic demo lifecycle." />}{settingsOnly ? <section className="elegex-card max-w-2xl p-6"><p className="elegex-eyebrow">ORGANISATION PROFILE</p><h2 className="mt-2 text-lg font-semibold text-[#14213D]">Workspace identity</h2><div className="mt-5 grid gap-4"><Field label="Workspace name" value={workspaceName || workspace.data?.organizationName} onChange={setWorkspaceName} /><Field label="Primary colour" value={workspace.data?.primaryColor} onChange={() => undefined} /><NativeSelect label="Timezone" value="UTC" onChange={() => undefined} options={["UTC", "Europe/London", "America/New_York"]} /></div><Button onClick={() => updateSettings.mutate({ name: workspaceName || workspace.data?.organizationName })} className="mt-6 rounded-xl bg-[#195FE6]">Save settings</Button></section> : <div className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><section className="elegex-card overflow-hidden"><div className="border-b border-[#EEF2F7] px-6 py-5"><p className="elegex-eyebrow">MEMBERSHIP</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">Workspace roles</h2></div><div className="divide-y divide-[#F0F3F8]">{(admin.data?.members || []).map((member: any) => <div key={member.membership.id} className="flex flex-col gap-3 px-6 py-4 sm:flex-row sm:items-center"><span className="grid h-9 w-9 place-items-center rounded-full bg-[#EAF1FF] text-xs font-bold text-[#195FE6]">{member.user.name?.split(" ").map((part: string) => part[0]).join("").slice(0, 2)}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#34435F]">{member.user.name}</p><p className="mt-1 text-xs text-[#7A879E]">{member.membership.title || member.user.email}</p></div>{member.membership.role === "owner" ? <Badge className="border-0 bg-[#EAF1FF] text-[#195FE6]">Owner</Badge> : <select value={member.membership.role} onChange={event => updateRole.mutate({ membershipId: member.membership.id, role: event.target.value as any })} className="h-9 rounded-lg border border-[#DFE7F3] bg-white px-2 text-xs font-semibold text-[#50617F]">{["admin", "manager", "member", "viewer"].map(role => <option key={role} value={role}>{pretty(role)}</option>)}</select>}</div>)}</div></section><div className="space-y-5"><section className="elegex-card p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#FFF0F2] text-[#D12B48]"><CircleAlert className="h-5 w-5" /></span><div><p className="elegex-eyebrow">DEMO CONTROLS</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">Reset unified demo data</h2></div></div><p className="mt-4 text-sm leading-6 text-[#667085]">Restore the complete synthetic tenant: six months of jobs and dispatch, materials, evidence, quotes, invoice links, reporting snapshots, staged-release evidence, documents, notifications, and audit history. Uploaded document metadata will be cleared.</p><Button variant="outline" disabled={reset.isPending} onClick={() => window.confirm("Restore the complete six-month Elegex demonstration data?") && reset.mutate()} className="mt-5 rounded-xl border-[#F7C7D0] text-[#C63550] hover:bg-[#FFF0F2] hover:text-[#C63550]"><ArrowUpRight className="mr-2 h-4 w-4" />Reset complete demo</Button></section><section className="elegex-card overflow-hidden"><div className="border-b border-[#EEF2F7] px-6 py-5"><p className="elegex-eyebrow">ACTIVITY LOG</p><h2 className="mt-1 text-lg font-semibold text-[#14213D]">Audit trail</h2></div><div className="max-h-72 divide-y divide-[#F0F3F8] overflow-auto">{(admin.data?.logs || []).map((log: any) => <div key={log.id} className="px-6 py-3"><p className="text-sm font-medium text-[#34435F]">{log.summary}</p><p className="mt-1 text-xs text-[#98A2B3]">{formatDistanceToNowStrict(new Date(log.createdAt), { addSuffix: true })}</p></div>)}</div></section></div></div>}</>;
}

function EmptyState({ icon: Icon, title, description, action }: { icon: any; title: string; description: string; action?: React.ReactNode }) { return <div className="grid min-h-72 place-items-center px-6 py-12 text-center"><div><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-[#EEF4FF] text-[#195FE6]"><Icon className="h-6 w-6" /></span><h3 className="mt-4 text-base font-semibold text-[#24324D]">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[#7A879E]">{description}</p>{action}</div></div>; }
function PageLoading() { return <div className="grid min-h-[60vh] place-items-center"><div className="flex items-center gap-3 text-sm font-medium text-[#667085]"><Loader2 className="h-5 w-5 animate-spin text-[#195FE6]" />Loading your workspace…</div></div>; }
function Forbidden() { return <div className="grid min-h-[60vh] place-items-center"><div className="max-w-md text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#FFF0F2] text-[#D12B48]"><ShieldCheck className="h-7 w-7" /></span><h1 className="mt-5 text-2xl font-semibold text-[#14213D]">This area is restricted</h1><p className="mt-3 text-sm leading-6 text-[#667085]">Your workspace role does not include access to administration controls.</p></div></div>; }
